test('source freshness caches real fresh profile storage wrappers without reparsing large originals per material',()=>{
 const f=fixture(),value=C.resolve(f.options);C.freeze(value,f.options);const memory=E.startBatch(M.newState(),{id:'essential-batch-cache-source',courseDay:8,words:value.words,now:BASE});f.storage.setItem(M.KEY,JSON.stringify(memory));let owner='one',memoryParses=0,planParses=0,answerReads=0;const profiles={current:()=>({id:owner,createdAt:'2026-01-01T00:00:00.000Z'}),assertFresh(){},storage:()=>({getItem:key=>f.storage.getItem(key),setItem(){throw Error('no writes');}})},memoryCore={...M,parseState(value){memoryParses++;return M.parseState(value);}},adaptiveCore={...Adaptive,parseState(value){planParses++;return Adaptive.parseState(value);}},answer=JSON.stringify({kind:'vocabulary-three-modes',essentialBatchId:'essential-batch-cache-source',words:value.words,padding:'x'.repeat(1000000)}),record={id:'original-cache-source',source:'essential-vocabulary',skill:'vocabulary',version:1,dayNumber:8,get answer(){answerReads++;return answer;}},records=[record],options={profiles,materials:D.materials,records,memoryCore,adaptiveCore};
 for(let i=0;i<200;i++)assert.ok(Exposure.read({...options,storage:profiles.storage()}).sourceGroups.includes('public-source:voa-l1-01'));assert.equal(memoryParses,1);assert.equal(planParses,1);assert.equal(answerReads,1,'the large original is parsed once, not once per candidate');record.version++;Exposure.read({...options,storage:profiles.storage()});assert.equal(answerReads,2,'a true record revision invalidates the record snapshot');owner='two';Exposure.read({...options,storage:profiles.storage()});assert.equal(memoryParses,3,'profile identity cannot reuse another profile result');const other={getItem:key=>key===Adaptive.KEY?JSON.stringify(Adaptive.newState()):f.storage.getItem(key)};assert.deepEqual(Exposure.read({...options,storage:other}).sourceGroups,[],'a different backing store with different state cannot reuse a cached result');
});

